cd /tmp/ds-runs/b112f1b0d8/analysis; python3 -I -c "
import sqlite3,json;c=sqlite3.connect('warehouse.db')
seg=[]
for p in('desktop','mobile'):
 for k in('US','other'):
  d={}
  for w,(a,b) in {'before':('2026-09-21','2026-09-27'),'after':('2026-09-28','2026-10-04')}.items():
   n,cl=c.execute('select sum(searches),sum(clicks) from search_daily where platform=? and country=? and date between ? and ?',(p,k,a,b)).fetchone();d[w]={'n':n,'k':cl}
  seg.append({'name':p+'_'+k,**d})
print(json.dumps({'segments':seg}))
ser=[{'period':r[0],'rows':r[1]} for r in c.execute('select date,count(*) from search_daily group by date')]
print(json.dumps({'series':ser,'target':'2026-10-04'}))
" > /tmp/o.txt; cat /tmp/o.txt | head -1
S=.claude/skills/ds-mode/checks/run.py
python3 $S mix_shift --json "$(sed -n 1p /tmp/o.txt)"
python3 $S completeness --json "$(sed -n 2p /tmp/o.txt)"

